<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
  :root {
    --red: #d8232a;
    --blue: #1f3fae;
    --yellow: #f2c200;
    --black: #111111;
    --white: #ffffff;
    --grey: #e9e9e6;
    --line: 10px;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: 'Archivo', 'Helvetica Neue', Arial, sans-serif;
    background: var(--white);
    color: var(--black);
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
  }
  .frame {
    max-width: 1100px;
    margin: 0 auto;
    border: var(--line) solid var(--black);
  }

  /* ---------- Hero: the painting itself, rebuilt as CSS grid ---------- */
  .hero {
    display: grid;
    grid-template-columns: 5fr 4fr 3fr;
    grid-template-rows: 3fr 2fr 2fr;
    gap: var(--line);
    background: var(--black);
    min-height: 88vh;
    position: relative;
  }
  .cell { background: var(--white); }
  .cell.red    { background: var(--red); }
  .cell.blue   { background: var(--blue); }
  .cell.yellow { background: var(--yellow); }
  .cell.grey   { background: var(--grey); }

  /* Reproduce the picture: large red top-right, small blue bottom-left,
     small yellow rectangle bottom-right, thick black lines, white ground. */
  .c1 { grid-column: 1 / 2; grid-row: 1 / 4; }
  .c2 { grid-column: 2 / 3; grid-row: 1 / 2; }
  .c3 { grid-column: 3 / 4; grid-row: 1 / 3; background: var(--red); }
  .c4 { grid-column: 2 / 3; grid-row: 2 / 3; }
  .c5 { grid-column: 2 / 3; grid-row: 3 / 4; background: var(--blue); }
  .c6 { grid-column: 3 / 4; grid-row: 3 / 4; background: var(--yellow); }

  .hero-title {
    position: absolute;
    left: 0; bottom: 0;
    background: var(--white);
    border-top: var(--line) solid var(--black);
    border-right: var(--line) solid var(--black);
    padding: 28px 32px;
    max-width: 62%;
  }
  .hero-title h1 {
    font-weight: 900;
    font-size: clamp(1.6rem, 4vw, 2.8rem);
    line-height: 1.05;
    letter-spacing: -0.02em;
    text-transform: uppercase;
  }
  .hero-title .sub {
    margin-top: 10px;
    font-size: clamp(0.95rem, 1.6vw, 1.15rem);
    font-weight: 500;
  }
  .hero-title .sub b { font-weight: 700; }

  /* ---------- Sections ---------- */
  section { padding: 56px 48px; border-bottom: var(--line) solid var(--black); }
  section:last-of-type { border-bottom: none; }
  h2 {
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    font-size: clamp(1.1rem, 2.4vw, 1.5rem);
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    gap: 14px;
  }
  h2 .chip {
    width: 22px; height: 22px;
    border: 4px solid var(--black);
    display: inline-block;
    flex: none;
  }
  .chip.red { background: var(--red); }
  .chip.blue { background: var(--blue); }
  .chip.yellow { background: var(--yellow); }

  /* Painter */
  .painter { display: grid; grid-template-columns: 1fr 1fr; gap: 0; }
  .painter .portrait {
    background: var(--black);
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: 1fr 1fr;
    gap: 6px;
    padding: 6px;
    min-height: 220px;
  }
  .painter .portrait span { background: var(--white); }
  .painter .portrait span.r { background: var(--red); }
  .painter .portrait span.b { background: var(--blue); }
  .painter .portrait span.y { background: var(--yellow); }
  .painter .bio { padding: 28px 32px; }
  .painter .bio p { font-size: 1.05rem; }
  .painter .bio .years {
    font-weight: 700;
    font-size: 1.6rem;
    margin-bottom: 8px;
    letter-spacing: -0.01em;
  }

